    return null;
  },
};

// ── FormField component ─────────────────────────────────────
function createFormField({ id, label, type, placeholder, icon, helperText, required }) {
  const wrapper = document.createElement('div');
  wrapper.className = 'form-field';

  // Label
  const lbl = document.createElement('label');
  lbl.htmlFor = id;
  lbl.innerHTML = label + (required ? ` <span class="required-star" aria-hidden="true">*</span>` : '');

  // Input wrapper + icon
  const inputWrapper = document.createElement('div');
  inputWrapper.className = 'input-wrapper';

  const iconSpan = document.createElement('span');
  iconSpan.className = 'icon';
  iconSpan.innerHTML = icon;
  iconSpan.setAttribute('aria-hidden', 'true');

  const input = document.createElement('input');
  input.type = type;
  input.id = id;
  input.name = id;
  input.placeholder = placeholder;
  input.autocomplete = id === 'email' ? 'email' : id === 'phone' ? 'tel' : 'name';
  if (required) input.setAttribute('aria-required', 'true');

  inputWrapper.append(input, iconSpan);

  // Helper text
  let helperEl = null;
  if (helperText) {
    helperEl = document.createElement('p');
    helperEl.className = 'field-helper';
    helperEl.id = `${id}-helper`;
    helperEl.innerHTML = `${icons.info} ${helperText}`;
    input.setAttribute('aria-describedby', `${id}-helper ${id}-error`);
  } else {
    input.setAttribute('aria-describedby', `${id}-error`);
  }

  // Validation message
  const errorEl = document.createElement('p');
  errorEl.className = 'validation-message';
  errorEl.id = `${id}-error`;
  errorEl.setAttribute('role', 'alert');
  errorEl.setAttribute('aria-live', 'polite');

  wrapper.append(lbl, inputWrapper);
  if (helperEl) wrapper.append(helperEl);
  wrapper.append(errorEl);

  // ── Validation logic ──
  function validate(showError = true) {
    const key = id === 'fullName' ? 'fullName' : id === 'email' ? 'email' : 'phone';
    const error = validators[key](input.value);

    wrapper.classList.remove('is-error', 'is-valid');

    if (error) {
      if (showError) {
        wrapper.classList.add('is-error');
        errorEl.innerHTML = `${icons.alert} ${error}`;
      }
      return false;
    } else {
      if (input.value.trim()) wrapper.classList.add('is-valid');
      errorEl.innerHTML = '';
      return true;
    }
  }

  input.addEventListener('blur', () => validate(true));
  input.addEventListener('input', () => {
    if (wrapper.classList.contains('is-error')) validate(true);
    else if (input.value.trim()) validate(false);
  });

  return { element: wrapper, validate, input };
}

// ── ContactForm component ───────────────────────────────────
function ContactForm() {
  const card = document.createElement('div');
  card.className = 'card';

  // Header
  const header = document.createElement('div');
  header.className = 'card-header';
  header.innerHTML = `
    <div class="badge">Support</div>
    <h1>Contact Us</h1>
    <p>Fill in the form below and our team will get back to you within one business day.</p>
  `;

  // Fields
  const nameField = createFormField({
    id: 'fullName',
    label: 'Full Name',
    type: 'text',
    placeholder: 'Jane Doe',
    icon: icons.user,
    required: true,
  });

  const emailField = createFormField({
    id: 'email',
    label: 'Email Address',
    type: 'email',
    placeholder: 'jane@example.com',
    icon: icons.email,
    required: true,
  });

  const phoneField = createFormField({
    id: 'phone',
    label: 'Phone Number',
    type: 'tel',
    placeholder: '+1 (555) 000-0000',
    icon: icons.phone,
    helperText: 'Optional. Format: +1 (555) 000-0000 or digits, spaces, hyphens, and parentheses.',
    required: false,
  });

  // Submit button
  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.className = 'btn-submit';
  submitBtn.innerHTML = `${icons.send} Send Message`;

  // Success banner
  const successBanner = document.createElement('div');
  successBanner.className = 'success-banner';
  successBanner.setAttribute('role', 'status');
  successBanner.innerHTML = `${icons.check} <span>Message sent! We'll be in touch soon.</span>`;

  // Form
  const form = document.createElement('form');
  form.setAttribute('novalidate', '');
  form.append(
    nameField.element,
    emailField.element,
    phoneField.element,
    submitBtn,
    successBanner,
  );

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const nameOk  = nameField.validate(true);
    const emailOk = emailField.validate(true);
    const phoneOk = phoneField.validate(true);

    if (nameOk && emailOk && phoneOk) {
      successBanner.classList.add('visible');
      form.reset();
      [nameField, emailField, phoneField].forEach(f => {
        f.input.parentElement.parentElement.classList.remove('is-valid', 'is-error');
      });
      submitBtn.disabled = true;
      submitBtn.style.opacity = '0.6';
    } else {
      successBanner.classList.remove('visible');
      // Focus first invalid field
      for (const f of [nameField, emailField, phoneField]) {
        if (f.input.parentElement.parentElement.classList.contains('is-error')) {
          f.input.focus();
          break;
        }
      }
    }
  });

  card.append(header, form);
  return card;
}

// ── Mount ───────────────────────────────────────────────────
document.getElementById('root').appendChild(ContactForm());
